<script setup lang="ts">
definePageMeta({ middleware: 'admin-auth' })
const navigationOpen = ref(false); const search = ref(''); const selectedStatus = ref('all'); const selectedType = ref('all')
const { getAdminRoutes } = useAdminRoutes(); const { data: routes, pending, error } = await useAsyncData('admin-routes', getAdminRoutes)
const name = (route: NonNullable<typeof routes.value>[number]) => route.route_translations.find(item => item.language_code === 'en')?.name ?? route.route_translations[0]?.name ?? 'Untitled route'
const types = computed(() => [...new Set((routes.value ?? []).map(route => route.route_type))].sort())
const filtered = computed(() => (routes.value ?? []).filter((route) => { const q = search.value.trim().toLowerCase(); return (!q || name(route).toLowerCase().includes(q) || route.slug.includes(q)) && (selectedStatus.value === 'all' || route.status === selectedStatus.value) && (selectedType.value === 'all' || route.route_type === selectedType.value) }))
const date = (value: string) => new Intl.DateTimeFormat('en-US', { month: 'short', day: 'numeric', year: 'numeric' }).format(new Date(value))
</script>
<template><div class="min-h-screen bg-slate-50 lg:pl-60"><AdminSidebar :open="navigationOpen" @close="navigationOpen = false" /><AdminHeader title="Routes" description="Manage curated travel routes and their stops." @menu="navigationOpen = true" /><main class="p-4 sm:p-6 lg:p-8"><section class="rounded-xl border border-slate-200 bg-white p-4 shadow-sm"><div class="mb-4 flex justify-end"><NuxtLink to="/admin/routes/new" class="rounded-lg bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Add route</NuxtLink></div><div class="grid gap-3 md:grid-cols-[minmax(0,1fr)_11rem_11rem]"><input v-model="search" type="search" placeholder="Search by name or slug" class="rounded-lg border border-slate-300 px-3 py-2.5 text-sm"><select v-model="selectedStatus" class="rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="all">All statuses</option><option value="published">Published</option><option value="draft">Draft</option><option value="archived">Archived</option></select><select v-model="selectedType" class="rounded-lg border border-slate-300 bg-white px-3 py-2.5 text-sm"><option value="all">All types</option><option v-for="type in types" :key="type" :value="type">{{ type }}</option></select></div></section><p v-if="pending" class="mt-6 rounded-xl bg-white p-5 text-sm text-slate-500">Loading routes…</p><p v-else-if="error" class="mt-6 rounded-xl border border-red-200 bg-red-50 p-5 text-sm text-red-700">Routes are unavailable right now.</p><p v-else-if="!routes?.length" class="mt-6 rounded-xl border border-slate-200 bg-white p-5 text-sm text-slate-500">No routes have been added yet.</p><p v-else-if="!filtered.length" class="mt-6 rounded-xl border border-slate-200 bg-white p-5 text-sm text-slate-500">No routes match the current filters.</p><section v-else class="mt-6"><div class="hidden overflow-hidden rounded-xl border border-slate-200 bg-white lg:block"><table class="w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase text-slate-500"><tr><th class="px-5 py-3">Route</th><th>Type</th><th>Stops</th><th>Duration</th><th>Difficulty</th><th>Status</th><th>Updated</th><th class="px-5 text-right">Actions</th></tr></thead><tbody class="divide-y divide-slate-100"><tr v-for="item in filtered" :key="item.id"><td class="px-5 py-4"><p class="font-medium text-slate-900">{{ name(item) }}</p><p class="text-xs text-slate-400">{{ item.slug }}</p></td><td class="capitalize">{{ item.route_type.replace('_', ' ') }}</td><td>{{ item.route_places.length }}</td><td>{{ item.duration_minutes ?? '—' }}<span v-if="item.duration_minutes"> min</span></td><td class="capitalize">{{ item.difficulty ?? '—' }}</td><td><AdminStatusBadge :status="item.status" /></td><td>{{ date(item.updated_at) }}</td><td class="px-5 text-right"><NuxtLink :to="`/admin/routes/${item.id}`" class="font-medium text-slate-700">Edit</NuxtLink><NuxtLink :to="`/routes/${item.slug}`" class="ml-4 font-medium text-blue-600">View</NuxtLink></td></tr></tbody></table></div><div class="grid gap-3 lg:hidden"><article v-for="item in filtered" :key="item.id" class="rounded-xl border border-slate-200 bg-white p-4"><div class="flex justify-between gap-3"><div><h2 class="font-semibold text-slate-900">{{ name(item) }}</h2><p class="text-xs text-slate-400">{{ item.slug }}</p></div><AdminStatusBadge :status="item.status" /></div><p class="mt-3 text-sm text-slate-600">{{ item.route_places.length }} stops · {{ item.duration_minutes ?? '—' }} min · {{ item.difficulty ?? 'Unspecified' }}</p><div class="mt-4 flex gap-4 text-sm font-medium"><NuxtLink :to="`/admin/routes/${item.id}`" class="text-slate-700">Edit</NuxtLink><NuxtLink :to="`/routes/${item.slug}`" class="text-blue-600">View</NuxtLink></div></article></div></section></main></div></template>
